import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Fused custom CUDA kernel for adding bias and applying ReLU
fused_bias_relu_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void fused_bias_relu_kernel(const float* input, const float* bias, float* output,
                                       int batch_size, int out_channels, int out_h, int out_w) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total = batch_size * out_channels * out_h * out_w;
    if (idx < total) {
        int c = (idx / (out_h * out_w)) % out_channels;
        float val = input[idx] + bias[c];
        // ReLU
        if (val < 0.0f) {
            val = 0.0f;
        }
        output[idx] = val;
    }
}

torch::Tensor fused_bias_relu_cuda(torch::Tensor input, torch::Tensor bias) {
    auto batch_size   = input.size(0);
    auto out_channels = input.size(1);
    auto out_h        = input.size(2);
    auto out_w        = input.size(3);

    auto output = torch::zeros_like(input);

    int total = batch_size * out_channels * out_h * out_w;
    int block_size = 256;
    int grid_size = (total + block_size - 1) / block_size;

    fused_bias_relu_kernel<<<grid_size, block_size>>>(
        input.data_ptr<float>(),
        bias.data_ptr<float>(),
        output.data_ptr<float>(),
        batch_size,
        out_channels,
        out_h,
        out_w
    );

    return output;
}
"""

fused_bias_relu_cpp_source = r"""
torch::Tensor fused_bias_relu_cuda(torch::Tensor input, torch::Tensor bias);
"""

# Compile the inline CUDA code
fused_bias_relu = load_inline(
    name="fused_bias_relu",
    cpp_sources=fused_bias_relu_cpp_source,
    cuda_sources=fused_bias_relu_source,
    functions=["fused_bias_relu_cuda"],
    verbose=False,
)

class ModelNew(nn.Module):
    """
    Optimized model with fused custom CUDA operator for bias addition + ReLU.
    """
    def __init__(self, in_channels, out_channels, kernel_size, bias_shape):
        super(ModelNew, self).__init__()
        self.conv = nn.Conv2d(in_channels, out_channels, kernel_size)
        self.bias = nn.Parameter(torch.randn(bias_shape))

    def forward(self, x):
        x = self.conv(x)
        x = fused_bias_relu.fused_bias_relu_cuda(x, self.bias)
        return x
